  format: filterFormate[] = [{ key: 'Format - All', value: null }, { key: 'EXT', value: 'EXT' }, { key: 'PDF', value: 'PDF' }, { key: 'DOC', value: 'DOC' }, { key: 'JPG', value: 'JPG' }, { key: 'TIFF', value: 'TIFF' }, { key: 'PNG', value: 'PNG' }];  // ['Format - All', 'EXT', 'PDF', 'DOC', 'JPG', 'TIFF', 'PNG'];


  sAction: any = 'Action - All';
  sStatus: any = 'Status - All';
